package com.bombay.restaurantintelligence.intake;
import com.bombay.restaurantintelligence.normalization.DuplicateSourceException; import com.bombay.restaurantintelligence.repository.*; import com.bombay.restaurantintelligence.storage.DocumentStorageService; import com.fasterxml.jackson.databind.ObjectMapper; import org.junit.jupiter.api.Test; import org.junit.jupiter.api.extension.ExtendWith; import org.mockito.*; import org.mockito.junit.jupiter.MockitoExtension; import org.springframework.mock.web.MockMultipartFile; import static org.assertj.core.api.Assertions.*; import static org.mockito.ArgumentMatchers.*; import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class UploadIngestionServiceTest {@Mock ExcelExtractor excel;@Mock CsvExtractor csv;@Mock AiExtractionProvider ai;@Mock DocumentStorageService storage;@Mock IngestionJobRepository jobs;@Mock SourceDocumentRepository docs;@Mock IntakeAgent intake;
 @Test void duplicateChecksumIsRejected(){when(jobs.existsByChecksum(anyString())).thenReturn(true);var s=new UploadIngestionService(excel,csv,ai,storage,jobs,docs,intake,new ObjectMapper());var f=new MockMultipartFile("file","purchase.csv","text/csv","a,b\n1,2".getBytes());assertThatThrownBy(()->s.preview(f)).isInstanceOf(DuplicateSourceException.class);}
 @Test void checksumIsDeterministic(){assertThat(UploadIngestionService.sha256("abc".getBytes())).isEqualTo("ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad");}
}
